// Accessor for this service's own D1 database.
//
// `Env` and `D1Database` are ambient global types generated by
// `wrangler types` into worker-configuration.d.ts from the `d1_databases`
// binding in wrangler.jsonc — no import needed here.
//
// Intentionally just a binding accessor: no repository/CRUD methods yet.
// Add those once a route actually needs them.

export function getDb(env: Env): D1Database {
  return env.learning_assistant_db
}
